plist.dict:
	Label
	io.lima-vm.daemon.{{ .Instance | xml }}
	UserName
	{{ .UserName | xml }}
	EnvironmentVariables

		LIMA_HOME
		{{ .LimaHome | xml }}
{{- if .Path }}
		PATH
		{{ .Path | xml }}
{{- end }}

	ProgramArguments

		{{ .Binary | xml }}
		start
		{{ .Instance | xml }}
		--foreground

	RunAtLoad

{{- if .KeepAlive }}
	KeepAlive

		SuccessfulExit


{{- end }}
	StandardErrorPath
	launchd.stderr.log
	StandardOutPath
	launchd.stdout.log
	WorkingDirectory
	{{ .WorkDir | xml }}
	ProcessType
	Background
